import{describe,it,expect,beforeEach}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url)),moduleCode=readFileSync(resolve(__dirname,"../../frontend/travel-timeline/travel-timeline.js"),"utf-8");function loadTravelTimeline(){return new Function(moduleCode)(),globalThis.TravelTimeline||window.TravelTimeline}describe("TravelTimeline engine",()=>{let t;beforeEach(()=>{localStorage.clear(),document.body.innerHTML="",t=loadTravelTimeline()}),describe("validation",()=>{it("requires a title and a valid start date",()=>{expect(t.validateTrip({})).toContain("Title is required"),expect(t.validateTrip({title:"Trip"})).toContain("A valid start date is required")}),it("rejects an end date before the start date",()=>{const e=t.validateTrip({title:"Trip",startDate:"2026-05-10",endDate:"2026-05-01"});expect(e).toContain("End date cannot be before start date")}),it("rejects an out-of-range rating",()=>{const e=t.validateTrip({title:"Trip",startDate:"2026-05-01",rating:9});expect(e).toContain("Rating must be between 1 and 5")}),it("accepts a minimal valid trip",()=>{expect(t.validateTrip({title:"Trip",startDate:"2026-05-01"})).toEqual([])})}),describe("duration calculation",()=>{it("treats a single-day trip (no end date) as 1 day",()=>{expect(t.computeDurationDays("2026-05-01","")).toBe(1)}),it("computes an inclusive day count across a date range",()=>{expect(t.computeDurationDays("2026-05-01","2026-05-05")).toBe(5)})}),describe("CRUD operations",()=>{it("adds a trip and persists it to localStorage",()=>{const e=t.addTrip({title:"Golden Triangle",state:"Uttar Pradesh",category:"heritage",startDate:"2026-01-10",endDate:"2026-01-14"});expect(e.id).toBeTruthy(),expect(e.durationDays).toBe(5),expect(t.getTrips()).toHaveLength(1);const a=JSON.parse(localStorage.getItem("india-explorer-travel-timeline"));expect(a).toHaveLength(1),expect(a[0].title).toBe("Golden Triangle")}),it("throws when adding an invalid trip",()=>{expect(()=>t.addTrip({title:""})).toThrow()}),it("updates an existing trip",()=>{const e=t.addTrip({title:"Kerala Backwaters",startDate:"2026-02-01"}),a=t.updateTrip(e.id,{rating:5,notes:"Unforgettable houseboat stay"});expect(a.rating).toBe(5),expect(a.notes).toBe("Unforgettable houseboat stay"),expect(a.title).toBe("Kerala Backwaters")}),it("returns null when updating a trip that does not exist",()=>{expect(t.updateTrip("missing-id",{rating:4})).toBeNull()}),it("deletes a trip",()=>{const e=t.addTrip({title:"Leh Ladakh",startDate:"2026-06-01"});expect(t.deleteTrip(e.id)).toBe(!0),expect(t.getTrips()).toHaveLength(0),expect(t.deleteTrip(e.id)).toBe(!1)}),it("returns trips sorted chronologically regardless of insertion order",()=>{t.addTrip({title:"Later trip",startDate:"2026-08-01"}),t.addTrip({title:"Earlier trip",startDate:"2025-03-01"}),t.addTrip({title:"Middle trip",startDate:"2025-12-01"});const e=t.getTrips().map(t=>t.title);expect(e).toEqual(["Earlier trip","Middle trip","Later trip"])})}),describe("filtering and search",()=>{beforeEach(()=>{t.addTrip({title:"Taj Mahal Weekend",state:"Uttar Pradesh",category:"heritage",startDate:"2025-11-01",endDate:"2025-11-03",destinationNames:["Agra"]}),t.addTrip({title:"Himalayan Trek",state:"Himachal Pradesh",category:"mountains",startDate:"2026-06-15",endDate:"2026-06-20",notes:"Snow-capped peaks and cold mornings"}),t.addTrip({title:"Goa Beach Escape",state:"Goa",category:"beaches",startDate:"2026-06-01",endDate:"2026-06-04"})}),it("filters by year",()=>{expect(t.filterTrips({year:2025})).toHaveLength(1),expect(t.filterTrips({year:2026})).toHaveLength(2)}),it("filters by state",()=>{const e=t.filterTrips({state:"Goa"});expect(e).toHaveLength(1),expect(e[0].title).toBe("Goa Beach Escape")}),it("filters by category",()=>{expect(t.filterTrips({category:"mountains"})).toHaveLength(1)}),it("searches across title, notes, and destinations",()=>{expect(t.filterTrips({query:"agra"})).toHaveLength(1),expect(t.filterTrips({query:"snow-capped"})).toHaveLength(1),expect(t.filterTrips({query:"nonexistent-place"})).toHaveLength(0)}),it("combines multiple filters",()=>{const e=t.filterTrips({year:2026,category:"beaches"});expect(e).toHaveLength(1),expect(e[0].title).toBe("Goa Beach Escape")}),it("lists distinct years and states for filter dropdowns",()=>{expect(t.getYears()).toEqual([2026,2025]),expect(t.getStates()).toEqual(["Goa","Himachal Pradesh","Uttar Pradesh"])})}),describe("stats",()=>{it("summarizes trip count, total days, states, and average rating",()=>{t.addTrip({title:"Trip A",state:"Goa",startDate:"2026-01-01",endDate:"2026-01-03",rating:4}),t.addTrip({title:"Trip B",state:"Kerala",startDate:"2026-02-01",endDate:"2026-02-05",rating:5});const e=t.getStats();expect(e.totalTrips).toBe(2),expect(e.totalDays).toBe(8),expect(e.statesVisited).toBe(2),expect(e.avgRating).toBe(4.5)}),it("returns null average rating when no trips are rated",()=>{t.addTrip({title:"Trip A",startDate:"2026-01-01"}),expect(t.getStats().avgRating).toBeNull()})}),describe("export",()=>{it("exports valid JSON containing every trip",()=>{t.addTrip({title:"Trip A",startDate:"2026-01-01"}),t.addTrip({title:"Trip B",startDate:"2026-02-01"});const{filename:e,mimeType:a,content:i}=t.exportTimeline("json");expect(e).toBe("travel-timeline.json"),expect(a).toBe("application/json"),expect(JSON.parse(i)).toHaveLength(2)}),it("exports CSV with a header row and one row per trip",()=>{t.addTrip({title:"Trip A",startDate:"2026-01-01"}),t.addTrip({title:"Trip, B",startDate:"2026-02-01"});const{filename:e,mimeType:a,content:i}=t.exportTimeline("csv"),r=i.split("\n");expect(e).toBe("travel-timeline.csv"),expect(a).toBe("text/csv"),expect(r[0]).toBe("title,state,category,startDate,endDate,durationDays,rating,notes"),expect(r).toHaveLength(3),expect(r[2]).toContain('"Trip, B"')})})});